          "originalNo": 10,
          "type": "choice",
          "category": "选择题",
          "stem": "室温下，测得某土壤施肥前后的pH由5.5变为6，可知该土壤施肥后（ ）",
          "answer": "A",
          "explanation": "施肥前，土壤的pH为5.5，小于7，说明土壤呈酸性；施肥后pH变为6，仍然小于7，说明土壤仍呈酸性。当溶液的pH小于7时，呈\n酸性，且pH越小，酸性越强，由于pH由5.5变为6，pH增大，说明酸性减弱，则该土壤施肥后仍呈酸性，但酸性减弱。\n故选：A。",
