          "stem": "根据回忆资料，完成下列默写。\n（1）潭西南而望，斗折蛇行，____。（柳宗元《小石潭记》）\n（2）无可奈何花落去，____。（晏殊《浣溪沙·一曲新词酒一杯》）\n（3）____，后不见来者。（陈子昂《登幽州台歌》）\n（4）小申在景点游玩时，看见山里风光明媚、鸟儿自在欢快地鸣叫，潭水清澈明净，他想起可以用常建《题破山寺后禅院》中‘____，____’两句来表示。",
          "answer": "（1）明灭可见。（2）前不见古人。（3）似曾相识燕归来。（4）山光悦鸟性，潭影空人心。",
