          "type": "written",
          "stem": "默写与运用。\n（ 1 ）造化钟神秀， ______ 。（杜甫《望岳》）\n（ 2 ）山气日夕佳， ______ 。（陶渊明《饮酒（其五）》）\n（ 3 ） ______ ，听取蛙声一片。（辛弃疾《西江月 • 夜行黄沙道中》）\n（ 4 ）小申同学在阅读时明白，作为当代的中国青年需要心怀家国，以天下为己任的人生目标，正如范仲淹在《岳阳楼\n记》中所写的那样 “______ ， ______” 。",
