          "type": "written",
          "stem": "阅读下文，完成下面小题。\n草茎上的流年\n       ①草尖拱出地面，旋转着嫩绿的茎叶，它缓缓地爬上我的脚背，沿脚踝绕上腿肚，呼啦啦覆盖了我的腰身，俨然绿\n色的河在我的身上倒流。\n       ②家乡人把狗尾巴草叫咪咪猫。狗尾巴和猫咪的共同点，大概是身上都毛茸茸的，依此给一种穗子上布满绒毛的小\n草冠名，贴切又亲切。\n       ③我用咪咪猫编兔子的本事，最先是和我二姐学的。编兔子不难，比和她下跳棋容易多了。和她下棋，我总是输，\n而编兔子，是不分输赢的。我一直觉得自己比她编得好看。\n       ④在我学会编草兔子不久，二姐又向我展示了咪咪猫的另一种玩法。她揪下一根咪咪猫，掐断细长的穗柄，将穗柄\n那端朝着天空，放进她握起来的拳头里。只见她的拳头一松一紧，一紧一松，随着她的口令，咪咪猫听懂话似的从她的\n手心里往外攀爬，一厘厘露出头和腰身来。二姐一边动作，一边口里念念有词，像是给手心里的咪咪猫施展魔法：咪咪\n猫，上高窑。金蹄蹄，银爪爪。上树树，逮雀雀。逮了雀雀喂老猫，扑棱扑棱飞完了。在她叽里咕噜说完最后三个字\n“ 飞完了 ” 时，原本待在她手心里的咪咪猫，果真踩着节点爬了出来，一下子没了踪影。\n       ⑤之后，有狗尾巴草的地方，随时放飞猫咪，也放飞烦恼焦虑，放飞我们对未来的期盼 ……\n       ⑥今年秋天，返回故乡途中，忽见路边长满了咪咪猫。我弯腰揪下两根，一根递给二姐。二姐一愣，随即掐掉长\n柄，把咪咪猫握在手心里，咪咪猫，上高窑，金蹄蹄，银爪爪 ……\n       ⑦这些儿时承载了美与快乐的草茎，在岁月的风尘里，纷纷成为发黄的老物件，如一张张过期的年画。我怀念童\n年，也许童年天真无邪、无比欢乐的我就像年画一样已经成为过去。也许咪咪猫一直陪伴着我，直至永远。\n（ 1 ）作者在选文第②段中提到，咪咪猫 “ 亲近而贴切 ” ，亲近的原因是  ______ ，贴切的原因是  ______\n（ 2 ）分析第⑤段三个 “ 放飞 ” 的语言表现力。\n（ 3 ）下列对文章的理解，正确的是  ______\nA ． “ 童年之我 ” 的叙述，语言生动，目的是为拉近与读者之间的距离。\nB ． “ 成年之我 ” 的叙述，突出了我百感交集之后的沧桑。\nC ．用不同的叙述和选材变化，可以来反应层次的变化，使文章层次丰富。\n（ 4 ）作者对咪咪猫的选材和组材，经过流年经历，表达了作者不同情感。请对此加以分析。",
