          "originalNo": 1,
          "type": "written",
          "stem": "默写。\n（ 1 ）山川之美， ______ 。（《答谢中书书》）\n（ 2 ）仍怜故乡水， ______ 。（《渡荆门送别》）\n（ 3 ） ______ ，不亦乐乎？（《＜论语＞十二章》）\n（ 4 ）小申在美术馆欣赏一幅山景图，画面上神奇秀丽的高山耸入云端，太阳照射下山的两面阴暗不同，他不觉吟诵了\n杜甫《望岳》中的两句： “______ ， ______ 。 ”",
