          "answer": "答案：\n（ 1 ）古来共谈\n（ 2 ）万里送行舟（注意 “ 舟 ” 的写法）\n（ 3 ）有朋自远方来\n（ 4 ）造化钟神秀    阴阳割昏晓（注意 “ 钟 ” 的写法）",
          "explanation": "本题考查名篇名句默写，对于文质兼美的名言名句，多数同学能熟读成诵，但在考试中却得不到分，其中一个重要原因是生僻字、\n难写字书写有误，一字之差，导致丢分，实在遗憾。这就要勤于动笔，重点突破。",
