          "answer": "（ 1 ）本题考查文章内容概括。概括第③④内容。\n第③段，根据 “ 原来，科研人员在被测物体周边放置缪子探测器 …… 通过数据分析计算实现被测物体的三维成像。缪子成像技术主\n要有两种成像原理 ” 可以知道这段内容写的是缪子成像技术的原理。\n第④段，根据 “ 具有无接触勘探、不受时空限制、不会对勘探物体造成任何伤害、绿色环保等特点（优点），但它的使用受客观条\n件影响较大（缺点） ” 可以知道这段内容写的是缪子成像技术的优缺点。\n（ 2 ）本题考查内容理解和辨析，\nA. 有误，结合第①段 “ 要想掌握人体的病灶情况，我们可以使用 B 超、 CT 、核磁共振等各种影像仪器 ” 可知，要想掌握人体的病灶情\n况，应使用这些设备；文章③中介绍了使用国内首套宇宙射线缪子成像设备给西安古城墙做一次 “CT” 检查城墙内部情况，这个\n“CT” 并非我们日常所理解、接触到的机器，而且并没有说可以用 B 超和核磁共振等技术来检查城墙内部情况。\nB. 有误，结合第②段 “ 用得最多的是钻孔法，就是通过在墙体上打孔取材的方式，来判断其内部情况。但这种勘探方式会直接破坏\n墙体，后期还需要对损坏部分进行修复 ” 可知，用钻孔法会直接破坏城墙。\nC. 正确。\nD. 有误，结合第③段 “ 根据缪子射线在物体中不同方向的穿透情况，搜集肉眼看不见的缪子计数，进而在计算机上进行分析，通过\n数据分析计算实现被测物体的三维成像 ” ，可知绘制城墙三维图像是通过数据分析计算实现的，而不是目测。\n故选 C 。\n（ 3 ）本题考查段落的作用。先概括本段内容，再考虑内容上是否和说明对象一致，是否对说明对象进行补充、拓展，再考虑结构\n上与上下文有何关联。\n结合 “ 前段时间，团队又有了新思路：是否可以使用缪子成像技术探测青藏高原的冰川厚度，明晰岩石边界？值得一提的是，兰州\n大学核技术创新与产业化团队都致力于将其本土化。现在团队这项技术的国产化率已经达到了 95% 左右 ” 可知，该段明确提出了缪\n子成像技术除了考古探测外，还可以应用于地质勘查、矿产勘探、集装箱检测等多个领域，展现了技术的广泛应用前景和巨大的潜\n在价值。这不仅丰富了文章的内容，也体现了技术发展的多样性和可能性。段末指出兰州大学核技术创新与产业化团队致力于技术\n的本土化，且国产化率已达到 95% 左右。这一信息不仅体现了科研团队对国家科技自立自强的贡献，也强调了技术自主可控的重要\n性。这与文章标题 “ 国产设备给西安古城墙做 ‘CT’” 和结尾部分关于 “ 实现技术的中国式现代化 ” 的呼吁相呼应，增强了文章的连贯性\n和说服力。所以不能删去。\n答案：\n（ 1 ）缪子成像技术的原理      缪子成像技术的优势与局限\n（ 2 ） C\n（ 3 ）第⑥段首先说明缪子成像技术有更广阔的空间，在此基础上提出了未来研究新思路，同时呼应标题。说明缪子成像技术本土\n化程度高，为第⑦段呼吁 “ 实现技术的中国式现代化 ” ，所以不能删去。",
          "explanation": "文章先列举了为人体做 CT 的实例，引出本文的说明对象：缪子成像技术，并引出下文对这一说明对象的具体介绍，最后介绍了缪\n子成像技术 ” 的发展前景。",
          "category": "现代文阅读"
