          "stem": "一、古诗文（35 分）\n（一）默写与运用（13 分）\n\n1. 山不在高，___________________。（刘禹锡《陋室铭》）\n2. 而今识尽愁滋味，________。（辛弃疾《丑奴儿·书博山道中壁》）\n3. ____________，在乎山水之间也。（欧阳修《醉翁亭记》）\n4. 傍晚时分，小华漫步山间，看到鸟儿结伴归巢，不由地用陶渊明《饮酒（其五）》中的诗句来形容所见之景：“__________，_____________。”",
