          "type": "written",
          "category": "文言文阅读",
          "stem": "（二）阅读下面选文，完成第 5—10 题（22 分）\n\n【甲】\n孔子东游，见两小儿辩斗，问其故。\n一儿曰：“我以日始出时去人近，而日中时远也。”一儿曰：“我以日初出远，而日中时近也。”\n一儿曰：“日初出大如车盖，及出日中则如盘盂，此不为远者小而近者大乎？”\n一儿曰：“日初出沧沧凉凉，及其日中如探汤，此不为近者热而远者凉乎？”孔子不能决也。\n两小儿笑曰：“孰为汝多知乎？”\n\n【乙】\n王丹麓病起畏寒，每当雪夕，闭户谨风。时幼子小能五岁，坐著膝上，曰：“大人寒，故畏风，抑①知风亦畏寒。”王问故，答曰：“风不畏寒，何由喜扑人怀？”\n王丹麓座客常满。有客谓孔子无须，众诘其说。客曰：“本②《孔丛子》，子思③告齐君曰：‘先君生无须眉，天下王侯不以此损其敬。’故知今像多须，误也。”时丹麓子鼎六岁，在侧应声曰：“然则孔子亦无眉耶？”客语塞。\n\n【注】①抑：则，就。②本：根据。③子思：孔子的孙子。\n\n5. 【甲】【乙】两文提到的孔子是_________学派的创始者。（2 分）\n6. 解释下列句中加点词。（4 分）\n   （1）及其日中如探汤（ ）   （2）孔子不能决也（ ）\n7. 对【乙】文画线句意思的理解，最恰当的一项是______（3 分）\n   A. 所以知道现今画像上的孔子有很多胡须，是不对的。\n   B. 所以知道现今像孔子一样的人有很多胡须，是不对的。\n   C. 所以知道现今画像上的孔子有很多胡须，是受人误导。\n   D. 所以知道现今像孔子一样的人有很多胡须，是受人误导。\n8. 【甲】文中孔子因“______________”而“问其故”；【乙】文中王丹麓因幼子小能说“_____________”而“问故”。（4 分）\n9. 【甲】文中两小儿辩论的话题是____________（用自己的话概括）；【乙】文中王丹麓的儿子鼎说“然则孔子亦无眉耶”的目的是____________。（5 分）\n10. 【甲】【乙】两文中的孩子都给了我们这样的启示：⑴____________；⑵_____________。（4 分）",
          "answer": "5. （2 分）儒家\n6. （每个 2 分）（1）热水   （2）判断\n7. （3 分）A\n8. （4 分，每空 2 分）见两小儿辩斗；抑知风亦畏寒\n9. （5 分）太阳早晨和中午距离人的远近；驳斥客人仅凭书中语句就判断孔子没有胡须的观点\n10. （4 分，每点 2 分）（1）不能一味听信权威，要自己亲身验证；（2）要多角度看待事物。",
