          "explanation": "本题考查关联词语选择、文章思路梳理与段落顺序分析。第 11 题看前后分句关系确定假设连词；第 13 题须从内容与结构（照应）两方面作答。",
          "explanationNote": "原文逐字转录自上述存档文本，参考答案保留原资料解释；主观题人工核对。依赖配图的小问已声明缺图。待语文教师审核。"
