          "explanation": "本题考查场景概括、语句赏析、词语表现力、补写与开放探究。第 16 题须答出修辞手法、表达效果与作者情感三层；第 18 题先表态再陈述理由。",
          "explanationNote": "原文逐字转录自上述存档文本，参考答案保留原资料解释；主观题人工核对。依赖配图的小问已声明缺图。待语文教师审核。"
