          "stem": "三、综合运用（20 分）\n\n阅读下面材料，完成第 19—21 题（20 分）\n\n读了初中《语文》规定的 14 本必读名著，同学们准备通过小组合作，编制一本阅读手册，便于查阅与分享。\n\n19.【步骤一：目录分类】同学们计划将名著按一定的分类方式编排目录（见原卷第 19 题左图），请完成填空。（4 分）\n   （1）___________________________\n   （2）___________________________\n20.【步骤二：板块设计】手册现有三个板块七个项目（见原卷第 19 题右图），如增设“思考感悟”栏目，应放入的“板块”是_________（3 分）\n   A. 阅读准备   B. 走进作品   C. 分享收获\n21.【步骤三：栏目编辑】\n   （1）编写完“内容概要”栏目后，一同学发现其中有误，下列有误的一项是______（3 分）\n       A. 贫苦女子简·爱为寻求人格独立、爱情和尊严而挣扎奋斗。（《简·爱》）\n       B. 唐僧师徒四人一路降妖伏魔，历经磨难，到西天取得真经。（《西游记》）\n       C. 阿龙纳斯等人乘坐尼摩船长的潜水艇，在大海中航行。（《海底两万里》）\n       D. 人力车夫祥子始终不愿与命运积极抗争，最终走向毁灭。（《骆驼祥子》）\n   （2）你想把以下文字编入“片段推荐”栏目，请写出一条推荐理由。（4 分）\n\n       保尔的小队在自己的地段上清扫积雪。直到这时保尔才体会到，寒冷给人造成的痛苦是多么难以忍受。奥库涅夫给他的那件旧上衣一点也不暖和，脚上那只旧套鞋老往里灌雪，并且好几次掉在了雪堆里。\n       ——《钢铁是怎样炼成的》\n\n   （3）编写《水浒传》“创意表达”栏目时，需要用一幅插图来表现小说主题。小组同学找到了两幅图片（见原卷第 21（3）题右图），请选择一幅，写一段 60 字左右的文字，阐述你的看法。（6 分）",
