          "stem": "（二）阅读下面三段选文，完成第 6—8 题（12 分）\n\n【甲】卖油翁（节选）\n乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，唯手熟尔。”康肃笑而遣之。\n\n【乙】核舟记（节选）\n通计一舟，为人五；为窗八；为篛篷，为楫，为炉，为壶，为手卷，为念珠，各一；对联、题名并篆文，为字共三十有四。而计其长，曾不盈寸。盖简桃核修狭者为之。嘻，技亦灵怪矣哉！\n\n【丙】口技（节选）\n于是宾客无不变色离席，奋袖出臂，两股战战，几欲先走。\n\n6. 《卖油翁》作者是________代的________（人名）。（2 分）\n7. 用现代汉语翻译下面的句子。（4 分）\n   而计其长，曾不盈寸。\n8. 【甲】文形象地表达出□□□□的道理；【乙】文细致地说明了核舟体积小、“容量”大的特点；【丙】文则生动地表现出宾客深信“火起”而□□□□的样子。我们可以用【乙】文中的一句话“________________”来赞叹卖油翁、核舟雕刻者、口技艺人的高超技艺。（6 分）",
