          "explanation": "本题考查关联词语选择、说明思路梳理、说明文语言准确性与段落作用。第 12 题前后为递进关系；第 14 题须先解词再说明限定作用；第 15 题须从内容（补充造船技术这一原因）与结构（照应末段）两方面作答。",
          "explanationNote": "原文逐字转录自上述存档文本，参考答案保留原资料解释；主观题人工核对。篇目与作文题已与上海市教育考试院专家评析交叉核对。待语文教师审核。"
