          "explanation": "本题考查词语语境义、情节梳理、插叙作用、语言表现力与标题选择。第 19 题须答出表现手法、表达效果与人物情感三层；第 20 题两个标题均可，先表态再陈述理由。",
          "explanationNote": "原文逐字转录自上述存档文本，参考答案保留原资料解释；主观题人工核对。篇目与作文题已与上海市教育考试院专家评析交叉核对。待语文教师审核。"
