          "type": "written",
          "category": "综合运用",
          "stem": "三、综合运用（11 分）\n\n阅读下面材料，完成第 21—23 题（11 分）\n\n学校开展“用优秀寓言故事滋养心灵”主题活动，你所在学习小组的同学们要创作一个课本剧——《我与愚公相遇在 2021 年》。\n（原卷此处配有“六月好剧 即将上演 敬请期待”海报图）\n\n21. 为配合课本剧演出，小组同学要做一幅海报，以下最适合作海报宣传语的一项是（    ）（3 分）\n    A. 线条的舞蹈  力量的旋律\n    B. 农夫荷锄立  老少话桑麻\n    C. 立下移山志  开辟新天地\n    D. 劳动的身影  理想的憧憬\n22. 小组同学查阅了创作课本剧的若干方法，你认为不适合本次创作的两项是（    ）（4 分）\n    A. 认真地阅读原作    B. 确立剧作主题    C. 颠覆人物的形象\n    D. 设计矛盾冲突      E. 拟写个性化台词  F. 追求离奇情节\n23. 为突显“用优秀寓言故事滋养心灵”的主题，体现积极昂扬的时代精神，小组同学正在设计课本剧的结尾，请你将以下台词补充完整。（4 分）\n    愚公  孩子，2021 年的今天，你在生活中遇到了什么“山”，你该怎么做？\n    我    ________________________________________\n    （掌声响起）",
