          "stem": "（二）阅读下面两段选文，完成第6-9题（12分）\n【甲】橘逾淮为枳（节选）\n王视晏子曰：“[[u]]齐人固善盗乎[[/u]]？”\n晏子避席对曰：“婴闻之，橘生淮南则为橘，生于淮北则为枳，叶徒相似，其实味不同。所以然者何？水土异也。今民生长于齐不盗，入楚则盗，得无楚之水土使民善盗耶？”\n王笑曰：“圣人非所与熙也，寡人反取病焉。”\n【乙】公输（节选）\n公输盘曰：“夫子何命焉为？”\n子墨子曰：“北方有侮臣者，愿借子杀之。”公输盘不说。\n子墨子曰：“请献千金。”\n公输盘曰：“吾义固不杀人。”\n子墨子起，再拜，曰：“请说之。吾从北方闻子为梯，将以攻宋。宋何罪之有？荆国有余于地，而不足于民。杀所不足而争所有余，不可谓智；宋无罪而攻之，不可谓仁；知而不争，不可谓忠；争而不得，不可谓强；义不杀少而杀众，不可谓知类。”\n公输盘服。\n6.两段选文都讲了春秋战国时期的故事，《橘逾淮为枳》选自《[[u]] [[/u]][[u]]   [[/u]][[u]]        [[/u]][[u]] [[/u]]》，《公输》选自诸子百家中[[u]] [[/u]][[u]]    [[/u]][[u]] [[/u]][[u]] [[/u]] 家的经典著作。（2分）\n7.用现代汉语翻译下面句子。（3分）\n齐人固善盗乎？\n\n8.下列对选文内容理解正确的一项是（  ）。（3分）\nA．【甲】文体现了楚王是个善于纳谏、知错能改的人。。\nB. 【乙】文突出公输盘是个狂妄自大、固执己见的人。\nC. 晏子的辩驳义正辞严、墨子的说理诙谐幽默。\nD. 言辞交锋后，晏子使对方理屈，墨子令对方折服。\n9.选文通过对话，表现出晏子和墨子都具有 [[u]]     [[/u]][[u]] [[/u]][[u]]   [[/u]]和[[u]]    [[/u]][[u]] [[/u]][[u]]   [[/u]]的特点。（4 分）",
