          "stem": "（三）阅读下文，完成第10-12题（12分）\n刘弇遇东坡\n刘伟明弇①少以才学自负，擢高第，中词科，意气自得，下視同辈。绍圣初，因游一禅刹，时东坡谪岭南，道庐陵，亦来游，因相遇，互问爵里②姓氏。伟明遽对曰：“庐陵刘弇。”盖伟明初不知其[[dot]]为[[/dot]]东坡。自谓[[dot]]名[[/dot]]不下人，欲以折服之也。[[u]]乃复问东坡所从来[[/u]]。公徐应曰：“罪人苏轼。”伟明始大惊，逡巡，致敬曰：“不意乃见所畏③。”东坡亦嘉其才气，相与剧④谈而去。\n【注】①刘伟明弇（yǎn）：弇是刘伟明的字。②爵里：爵，爵位；里，故乡。③不意乃见所畏：没想到竟然见到我敬畏的人。④剧：痛快。\n10.解释下列句中加点词。（4分）\n（1）盖伟明初不知其[[u]]为[[/u]]东坡（   ）（2）自谓[[u]]名[[/u]]不下人（    ）\n11.对画线句的理解，最恰当的一项是（   ）。（3分）\nA.（伟明）于是又问东坡从什么地方来\nB.（伟明）于是反复问东坡从什么地方来\nC.（伟明）于是又问东坡是跟着谁来的\nD.（伟明）于是反复问东坡是跟着谁来的\n\n12.文中两人互问爵里姓氏，刘弇“遽对曰：‘庐陵刘弇’”的目的是“ ________________________” 而东坡则回避答爵里只答“罪人东坡”，原因是________________________________ ，________________，最终东坡以“________________” 的举动，展现了一代大家的风范。（5分）",
