          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "（四）阅读下文，完成第11-13题（11分）\n\n耕者王清臣\n天启初，颍川张远度买田颍南之中村，地多桃花林。一日，携榼①独游，见耕而歌者，徘徊疃②间，听之，皆杜诗也。遂呼与语，耕者自言王姓，名清臣，旧有田，畏徭役，尽委诸其族，今为人佣耕。[[dot]]少[[/dot]]曾读书。客有遗一册于其舍者，卷无首尾，读而爱之，[[dot]]故[[/dot]]尝歌，亦不知杜甫为何人也。[[u]]异日远度过其庐[[/u]]，见旧历背煤字漫灭，乃烧细枝为笔所书③，皆所作诗，后经乱不知所在。 \n【注】①榼：古代盛酒或贮水的器具。②瞳：村庄。③见旧历背煤字漫灭，乃烧细枝为笔所书：看到旧的历书背后，用烧过的树枝写的字模糊不清。\n\n11.解释下列句中加点词。（4分）\n（1）[[dot]]少[[/dot]]曾读书（      ）       （2）[[dot]]故[[/dot]]尝歌（      ）\n12.下列对画线句的理解，正确的一项是（   ）（3分）\nA.这一天张远度到他家拜访    B.过几天张远度到他家拜访\nC.过几天张远度经过他家      D.这一天张远度经过他家\n13.张远度来到“________”（用本文语句回答）的“颖南之中村”，见到王清臣，主动与他交谈的原因是________。（用自己的话回答）。（4分）",
          "answer": "11.（1）年幼    （2）所以    12.B\n13.地多桃花林    王清臣边耕种边吟唱杜甫的诗，令张远度很是惊奇",
