          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "三、综合运用（11分）\n阅读下面材料，完成第23-25题（11分）\n面具是人类历史上具有特殊意义的文化艺术。你受邀参加“面具文化”博览会，在入口处你收到一张活动单。\n活动单：面具——世界文化的脸。欢迎你接受三项挑战：①参观中国面具馆，为这张书签配一句宣传语；②在中国面具馆，向一位陌生人介绍一张你熟悉的“花脸”面具；③在欧洲面具馆的留言板上，写下参观感悟。图示名称：方正小篆体“面”、花脸（关羽）、“假面舞会”面具。\n\n23.最适合中国面具馆书签的一句宣传语是（4分）\nA.走进博览会，聆听大千世界的声音\nB.走近面具，一起了解世界文化遗产\nC.汉字—带领我们走向神秘的面具世界\nD.面具—历史深处走来的中国文化使者\n\n24.在中国面具馆，一位外国友人对一幅你熟悉的花脸（关羽）面具很感兴趣，你想给他作些介绍，以下最符合情境的说话顺序是（3分）\n①互留地址②介绍课文《花脸》\n③介绍面具知识④与对方打招呼\n⑤讲述桃园结义的故事\nA.③①②⑤④   B.④③⑤②①\nC.③①④②⑤   D.④②⑤①③\n\n25.在欧洲面具馆“假面舞会”面具展的留言板上，你看到了一句有意思的话“希望假面仅仅出现在舞会上”，触发了你对假面与生活的思考，你也准备写一句有意义的话。（运用一种修辞手法）（4分）\n________\n【配图】面具文化活动单见本题下方。",
          "answer": "23 D    24. B    \n25. 示例：舞会可以假面，生活不可假面。",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
