          "category": "古诗文默写",
          "stem": "1.默写\n（1）空山新雨后，______。（王维《山居秋暝》）\n（2）_______，草色入帘青。（刘禹锡《陋室铭》）\n（3）青山绿水，______。（白朴《天净沙·秋》）\n（4）_______，不耻下问，是以谓之文也。（《孔孟论学》）\n（5）月上柳梢头，______。（欧阳修《生查子·元夕》）",
          "answer": "(1). 天气晚来秋    (2). 苔痕上阶绿    (3). 白草红叶黄花    (4). 敏而好学    (5). 人约黄昏后",
          "explanation": "这是考查学生默写古诗的能力。复习古诗名句，首先是要熟练背诵古诗名篇和名句；其次是要字字落实，默写中不能出现错别字、更不能丢字添字。默写时，要注意“苔、痕”几个易错的字形。写完之后，要重新读一下诗句，看有没有张冠李戴的现象发生。",
          "review": {
            "status": "pending"
          }
