          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "阅读下文，完成后面小题\n（傅）文忠不谈诗文，而极爱[[dot]]才[[/dot]]。余在直①时最贫，一貂帽已三载，毛皆拳缩如蝟②。一日黎明，公在隆宗门外小直房，独呼余至，探怀中五十金授余，嘱[[dot]]易[[/dot]]新帽过年。[[u]]时已残腊卒岁，资正缺[[/u]]，五十金遂以应用。明日入直，依然旧帽也。公一笑不复言。呜呼！此意尤可感已③。\n【注释】①直：同“值”，当值，值勤。②蝟：今作“猬”，刺猬。③已：语气词。\n7. 解释文中加点的词\n⑴而极爱才（      ）      ⑵嘱易新帽过年（      ）\n8. 下列对画线部分意思的理解，最恰当的一项是（   ）\nA. 当时已是年终岁末，（我）正缺钱\nB. 当时（我）已风烛残年，还正缺钱\nC. 当时已是年终岁末，（我）资历不够\nD. 当时（我）已风烛残年，还精力不济\n9. 对我“依然旧帽”，公的表现是“________”；文末作者说“此意尤可感”，这里的“此意”是指__________。",
          "answer": "7.     (1). ⑴很（非常）    (2). ⑵换（更换）    8. A    \n9.     (1). 一笑不复言    (2). 傅文忠对我的尊重和体恤",
