          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "阅读下文，完成后面小题。\n不可或缺的城市风景——斑马线\n①说起斑马线，我们最熟悉的，由多条相互平行的白实线组成的人行横道线，因【kù sì】斑马身上的条纹而被称为斑马线。\n②斑马线的起源可以追溯到古罗马时期的“跳石”（见右图）。当时四轮马车与行人混行引发了许多道路堵塞和交通事故。于是，人们在马路上砌起凸出路面的“跳石”，行人可以踩着它们穿越马路。“跳石”成为一种指示行人过街的标识，这就是斑马线的祖先。1951年10月31日，世界上第一条斑马线在英国诞生。\n\n③最有名的斑马线也在英国。1969年，著名的披头士乐队发行了最后一张唱片——《艾比路》，该唱片的封面为四位歌手走在伦敦艾比路的一条斑马线上。2012 年，艾比路斑马线被英国政府提升到文物地位，成为伦敦的文化地标。\n④斑马线像是拦腰搭在道路上的白色飘带，看似简单朴素，却不是随意画出来的。按照设置规范，斑马线最小宽度为3米，可以根据行人流量以1米为一级予以加宽，行人越多的地方斑马线越宽。构成斑马线的白色平行粗实线的线宽为40～45厘米，两条平行粗实线之间的距离为60～80厘米。在什么情况下需要设置斑马线呢？一是未设置人行过街设施的路口，二是行人横过道路较为集中的路段。\n⑤作为城市交通生态中的一个重要标识，斑马线在指引车辆和行人有序通行、保护行人安全方面具有重要的作用。在漫漫车流中，法律赋予了斑马线上行人优先的路权，机动车临近时须减速避让，遇到行人正在通过时还应停车让行。斑马线作用的发挥，需要机动车尊重行人的路权，也需要行人珍惜自己的权利，两者缺一不可。\n⑥然而，现状并不令人乐观。由于机动车和行人互争斑马线，致使斑马线成为交通事故的多发地。据统计，[[u]]我国近三年发生在斑马线上的交通事故多达1.4万起，致死人数高达3898人[[/u]]。机动车未按规定让行，行人在斑马线上“散步”等是导致事故的主要原因。\n⑦现在，为了提高斑马线的醒目程度，更好地发挥其作用，有的城市在斑马线色彩搭配和视觉效果等方面进行了大胆尝试，如彩色斑马线、3D立体斑马线等。随着手机的普及， “低头族”看手机过马路成为新的安全隐患，为此有的城市推出了闪灯斑马线——在斑马线上安装多条醒目的灯带，斑马线在灯带的映照下与路口的信号灯同步变换颜色，为“低头族”过马路提供有效的警示。\n⑧斑马线是城市中一道不可或缺的风景。唯有守法守序，才是对这道风景的最好守护——这，需要每一个人的努力。\n10. 根据拼音写汉字。   kù sì______\n11. 下列对第④段内容的理解，正确的一项是\nA. 斑马线的宽度根据规范不应超过4米。\nB. 构成斑马线的白色粗实线须平行排列。\nC. 斑马线的宽度与人流量无关。\nD. 所有的路口都应设置斑马线。\n12.依据文本内容，摘录相关信息并作概括，完成下表。\n表头：信息摘录｜信息概括\n第一行：摘录（1）________（斑马线的祖先）｜概括：斑马线的起源。\n第二行：摘录：1951年，世界上第一条斑马线在英国诞生；（2）________｜概括：斑马线之“最”。\n第三行：摘录：指引车辆和行人有序通行；（3）________｜概括：（4）________。\n13. 第⑥段画线句运用了列数字的说明方法，作用是_______________。\n14. 文中提到，有的城市对斑马线设置进行了大胆尝试，你是否认同？请结合文本内容简述理由。\n【配图】古罗马跳石见本题下方。",
          "answer": "10. 酷似    11. B    \n12. ⑴古罗马时期的“跳石”  ⑵最有名的斑马线是（英国伦敦）艾比路斑马线⑶保护行人安全⑷斑马线的作用    \n13. 具体说明近三年来，我国发生在斑马线上的交通事故之多，后果之严重，强调了重视斑马线作用的重要性。    \n14. 【答案示例1】认同。这些大胆尝试增强了视觉效果，使斑马线更醒目，让行人和车辆能更清楚地注意到斑马线，尤其是为“低头族”提供了有效的警示，能更好地发挥斑马线的作用。【答案示例2】不认同。斑马线有严格的设置规范，对其颜色、宽度、间距等都有明确的规定，随意改变既不符合设置规范，也有可能对路人的视觉造成干扰，不利于发挥斑马线的作用。",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
