          "category": "作文",
          "stem": "23.题目：真的不容易\n要求：⑴写一篇600字左右的文章。⑵不得透露个人相关信息。⑶不得抄袭。",
          "answer": "作文没有唯一答案。原资料示例：\n参考例文\n真的不容易\n何称妙章，属斐然之章节，且令人思而无穷也？“言之无文，行而不远”大概是挖人深醒的真谛吧，此时此刻叹：语文，说爱你不容易。\n曾经的我，从汉语拼音到学习汉字、词语、和成语，再到达一个崭新的阶段，是你一步一步的让我积累，是你把我从文盲带领到一个有修养且彬彬有礼的学生。\n“长风破浪会有时，直挂云帆济沧海”是李白男子汉自强不息的精神；“一蓑烟雨任平生”是苏轼不畏坎坷的超然情怀，语文一次一次的让我陶醉于你的怀抱，又一次一次的升华我的人生观。这难道就是所谓的不能自拔、学海无涯？“少壮不努力，老大徒伤悲”是你引导我人生的导航；“读书破万卷，下笔如有神”是你弄清在迷路的我，才有今时的成就！其实，语文，说爱你不容易。\n有人说，语文是华丽的包装，依我说，是深藏不露？自我感受：文章虽是文采斐然，但却埋藏着深奥的含意，有些是曲折离奇的；有些是激励人生的；有些是意料之中的；有些是……语文，我真是摸不透你的心，还是我不够资格？语文，说爱你不容易。\n曾几何时，我想舍弃你，但却得到这个结论：迷则厌，厌则爱。原来一直都是因果循环，我没有舍弃你的理由，只有仰慕的目光，只有向往的精神，无论如何的变化，我终究还是倚着你，直到有一天你接受我的爱，不然我一直哀叹：语文，说爱你不容易。\n语文是一个大家庭，里面住着：纵情山水的太白，豪迈的苏东坡，斐然的李清照，还有许多许多……也令我了解他们的情怀，太白弃官场之九霄云外，为的是“且放白鹿青崖间，须行即骑访名山”的诗意生活，苏东坡一生与诗融为一体，他的激情大气，激起了我的共鸣，他的诗句超然脱俗且气势凌人。李清照那声声慢：“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”的凄掺情感被我永远铭记于心，这让我想起了“问君能有几多愁，恰似一江春水向东流。”相信不久的将来，我会认识更多的成员，希望我会更深入了解他们，更希望与他们结交“亲朋密友！”\n爱之者，安能轻易舍之向反方挥步远去也？稍有所悟曰：语文，说爱你不容易。",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
