          "type": "written",
          "category": "古诗文默写",
          "stem": "1．默写\n（1）斗折蛇行，　   　。（柳宗元《小石潭记》） \n（2）锦帽貂裘，　   　。（苏轼《江城子•密州出猎》\n（3）　   　，落日故人情。（李白《送友人》）\n（4）试问卷帘人，　   　  。（李清照《如梦令》）\n（5）　   　，草盛豆苗稀。（陶渊明《归园田居》）",
          "answer": "答案：（1）明灭可见\n（2）千骑卷平冈（重点字：冈）\n（3）浮云游子意\n（4）却道海棠依旧\n（5）种豆南山下",
