          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "4．阅读下文，完成下列各题\n    人有馈一木者，家僮曰：“留[[dot]]以[[/dot]]为梁。”余曰：“木小不堪也。”僮曰：“留以为栋。”余曰：“木大不宜也。”僮笑曰：“[[u]]木一也，忽病其大，又病其小[[/u]]。”余曰：“小子听之，物各有宜用也，岂惟木哉？，’\n他日，为余生炭满炉，烘人。余曰：“太多矣。’’乃[[dot]]尽[[/dot]]湿之，留星星三二点，欲明欲灭。 余曰：“太少矣。”僮怨曰：“火一也，既嫌其多，又嫌其少。”余曰：“小子听之，情各有所适也，岂惟火哉？ ”\n（1）解释文中加点的词。\n①留以为梁　   　②乃尽湿之　   　\n（2）对画线句意思理解最恰当的一项是　   　\nA．木料只有一根，（你）忽而痛恨它大，忽而又痛恨它小。\nB．木料只有一根，（你）忽而嫌弃它大，忽而又嫌弃它小。\nC．木料是同一根，（你）忽而嫌弃它大，忽而又嫌弃它小。\nD．木料是同一根，（你）忽而痛恨它大，忽而又痛恨它小。\n（3）文中两件事情分别告诉了我们什么道理？（用自己的话回答）\n第一件：　   　。\n第二件：　   　。",
          "answer": "（1）查对常见文言词（实、虚词）意义的理解及知识的迁移能力．解答本题要词语在句子里的意思，词义可根据知识的积累结合原句进行推断．\n①句意为：留下可以做成房梁．为：作为、做成．\n②句意为：他把炭都用水浇灭了．尽：全、都．\n（2）本题考查的是重点句子的翻译，做该题时，要忠于原文、不遗漏、不随意增减内容，译文要顺畅．注意重点字词以及常见句式的翻译，以直译为主，意义为辅．重点词语有：病：嫌弃；句意为：木料是同一根，（你）忽而嫌弃它大，忽而又嫌弃它小；故选C．\n（3）本题考查学生对文言文内容的理解与分析的能力．答题时需要通晓全文大意即可．文中两件事情分别告诉了我们的道理是：事物都有它合适的用途；做事情要掌握好分寸．\n答案\n（1）①作为、做成  ②全、都\n（2）C\n（3）事物都有它合适的用途；做事情要掌握好分寸\n　\n二、现代文",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
