          "stem": "5．阅读下文，完成下列各题\n无人机时代正在到来\n①正在到来的第四次工业革命将使人类进入“无人机时代”。各种类型的机器人纷纷问世，其中会飞的机器人──“无人机”异军突起，频频出现在公众的视野中。\n②无人机，实际上就是具有飞机形状的遥控飞行装置，主要由机身、 动力、 螺旋桨、录音、摄像、遥控、传输以及感应等部件构成。\n③无人机的发展始于军事领域。上世纪60年代，美国军方率先使用无人机进行运输、侦查、攻击等。之后，无人机被许多国家运用到军事领域，并且不断创新发展。目前，我国的军用无人机在技术上已经能够通过遥控准确无误地击中目标。\n④无人机由军用进入民用领域后，用途十分广泛。地质勘探、电网巡检、交通流量统计、大气污染检测等，都可以借助无人机的一臂之力。当地震、洪水、爆炸等灾害发生，无人机可快速飞至救灾人员无法抵达的现场，实施救援。2013年，四川芦山地震后，在交通中断的情况下，就是通过无人机航拍灾区情况，为救灾提供了第一手资料。\n⑤随着生产技术的日趋成熟，无人机的造价大幅降低。有资料表明，目前迷你无人机的制造成本已降低到三年前的十分之一[[dot]]左右[[/dot]]，因此，这类曾经带有神秘色彩的无人机，已经成为集实用与娱乐功能于一体的高端玩具，进入了普通人的生活。今天，只要你登录知名的电商平台，就可以搜索到各种型号的玩具无人机，其中数千元的就有GPS定位和图传功能，通过手机APP就能操控，航拍图象清晰，深受消费者青睐，具有广阔的市场前景。\n⑥科学技术的发展总是双刃剑。民用无人机的快速发展，也会给公共安全带来隐患。 美国白宫的草坪上，就曾有小型无人机坠落。自2016年以来，上海、重庆、南京等地的国际机场都遭遇过无人机的干扰，动辄就影响百余次航班起降，经济损失巨大。我国从2017 年6月1日起，已正式对质量在250克以上的民用无人机，实施实名登记注册。\n⑦近年来，随着纳米、仿生机器人技术的突飞猛进，出现了外形似鸟或昆虫的微型无人机，如纳米蜻蜓无人机，翼展仅5厘米，可从窗户飞进飞出，一旦飞进普通人的住宅， 个人隐私就会受到侵犯。也许数年之后，停在你书房角落里的一个蜘蛛，飞到你眼前的一只苍蝇，或者落在你窗口歌唱的美丽小鸟，正是一架微型的仿生无人机呢！\n⑧无人机的时代正在到来，它会走向何方？这不单是政府应该思考的问题，也是所有 人应该思考的问题。\n（1）第①段“异军突起”在文中的意思是　   　\n（2）对第④段内容的理解和分析，正确的一项是　   　\nA．第一句话表明对无人机的介绍由军用转入民用。\nB．本段通过大量详实的事例来介绍无人机的作用。\nC．芦山地震的例子说明无人机已能完全替代人的工作。\nD．本段的例子是为了说明中国无人机的发展领先世界。\n（3）第⑤段中加点词“左右”能否删去？请说明理由。\n（4）依据文章内容，概括无人机在使用中的利与弊。\n利：（1）　   　；（2）　   　。\n弊：（1）　   　；（2）　   　。\n（5）无人机对我们日常生活的影响越来越大。请展开想象，另举一例加以说明。（不得使用\n文中的例子）",
          "answer": "（1）本题考查文中关键词语含义的理解．解答此题要在理解词语本敲锣打鼓基础上，分析其语境义．异军突起，比喻一支新生力量突然出现．结合语境来看，指无人机在机器人领域中作为一支新生的力量，迅速崛起．\n（2）本题考查对说明内容的理解与分析．解答此题要在读懂文段的基础上，对四个选项进行仔细的分析．A、首句“无人机由军用进入民用领域后，用途十分广泛”，表明本段对无人机的介绍由军用转入民用．分析正确．B、第四段举了无人机在“地质勘探、电网巡检、交通流量统计、大气污染检测”“地震、洪水、爆炸等灾害发生”，只具体地举了2013年，四川芦山地震一个例子，分析有误．C、芦山地震的例子说明，在交通中断的情况下，无人机航拍可以为救灾提供第一手资料，但并没有表明无人机已能完全替代人的工作，分析有误．D、本段主要说明“无人机由军用进入民用领域后，用途十分广泛”，选项的内容属于无中生有，分析有误．故选A．\n（3）本题考查说明语言的特点．结合语境，具体分析其在文中的作用以及去掉之后的意思变化，最后点明说明文语言准确性的特点．答题模式为：先表态，然后指出词语的本义和语境义，接着分析删去后有什么不同，进而明确这个词体现了说明文语言准确性的特点．本句中的“左右”不能删去．因为“左右”表示概数，如果删去，则表示制造成本正好是三年前的十分之一，这就会与事实不符，最后再强调一下，用“左右”体现了说明文语言的准确性与严密性．\n（4）本题考查说明内容的归纳与概括．解答此题在了解全文内容的基础上，即可从文中找到相对应的内容，用自己的话加以概括即可．\n文章在前五段主要分析无人机给人类带来的便利，六七两段分析其弊端．结合这些段落中的内容分别概括现两点．\n（5）本题考查对作品进行个性化阅读和有创意的解读．结合文中的介绍与举例，展开想象，写出无人机在人类生活中越来越重要的作用即可．如：可利用无人机送外卖．\n答案：\n（1）无人机在机器人领域中迅速崛起．\n（2）A\n（3）不能删去．“左右”表示概数；如果删去，则表示制造成本为三年前的十分之一，是个确数，与事实不符；用“左右”体现了说明文语言的准确性与严密性．\n（4）利：①军用无人机可进行运输、侦察、远程攻击等，提升国家军事实力；\n②民用无人机可广泛运用于科研、交通安全、环保、救灾、娱乐等领域．\n弊：①给公共安全带来隐患；②可能侵犯公民隐私．\n（5）示例：可利用无人机送外卖，方便、快捷，能避开交通拥堵．",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
