          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "6．阅读下文，完成下列各题\n十七岁那年的单车\n①十七岁那年，刘伟看到别人骑着单车跑来跑去，十分xiàn mù，吵着要母亲买一辆。父亲横着眼说：“别做梦！有本事自己去买！”\n②刘伟发了一个月脾气。母亲心疼儿子，就买了一辆旧单车，在一个夏日的午后推回了家。刘伟骑上单车就跑，天天呼朋唤友，在集镇上闲逛。只有在外面没处混的时候，他才会回家，迎接他的自然是父亲铜铃般的眼珠子。刘伟把他爹当空气，吃完饭，跨上单车又风一样飘走了。\n③那一天，刘伟没有骑车出门。单车在墙角拧着脖子，父亲越看越来气，举起一把锄头，攒足力气砸了下去。单车散了架。“你──”刘伟正从外面回来，抄起一根扁担，横在父亲面前。母亲赶紧跑过去夺下了扁担。\n④父亲本来体弱，这回又气又恨，病倒了。\n⑤第二天，刘伟在埋头收拾衣服，母亲惊诧地问：“你要干啥？” “你别管。”刘伟头也不回，     ，走了。\n⑥“有本事你就别回来！”病床上的父亲吼道。\n⑦刘伟走后，母亲每天晚上都会把刘伟的饭留在锅里。半夜，父亲起来喝水，总忍不住揭开锅盖看看。\n⑧刘伟真的有半个月没回家了。母亲急了，找男人吵。父亲便四处打听刘伟的下落。\n⑨母亲依然每天都给刘伟留饭。父亲依然每晚都揭开锅盖看一眼。\n    ⑩两个月后的一天中午，母亲在打盹，听到屋里有响声，睁开眼。儿子正打着赤膊一门心思地擦着一辆新单车。父亲斜着眼看他，他装着不知道。\n    ⑪母亲万分高兴，跑到厨房打了一大碗溏心鸡蛋。刘伟吃着鸡蛋，母亲在一边说：“这次你爸的病一直不见好，今天你把他驮到医院看一下啊！”\n    ⑫刘伟不作声，站在单车旁，低头摸着崭新的龙头。父亲不愿意，母亲硬把他推到单车边，架了上去。\n    ⑬刘伟在前面使劲蹬车。父亲紧紧地拽着座凳下的立杆。父子俩你不理我，我不理你。走了一程， 父亲手一松，就从单车上掉下来了。\n    ⑭刘伟两条长腿支挺了车，不耐烦地说：“又怎么了？”\n    ⑮ “我不走了。”父亲说，“你这辆车是哪里弄来的？借的？偷的？抢的？”\n    ⑯ “关你什么事！”\n    ⑰ “我是你爹！”\n    ⑱“起来！”\n    ⑲父亲没动。\n    ⑳“不起来拉倒！”刘伟按了一把车铃，“丁零零”跑了！\n    ㉑父亲爬起来，拍拍屁股，看见刘伟又把单车骑回来了。\n    ㉒“我说单车是给人家搬砖挣钱买的，你信不信？ ”刘伟的口气缓和了一些。\n    ㉓父亲看了看儿子，脸和胳膊都晒得黑黝黝的。“这还差不多。”他嘟哝了一句，就往单车上坐。儿子伸手拉了他一下：“我要冲了，你抓牢。”\n    ㉔父亲[[dot]]犹豫[[/dot]]了一下，伸出手环住了儿子的腰。刘伟身体[[dot]]一震[[/dot]]，顿了一下，脚下一用力，单车就飞跑起来，身后留下了一串[[dot]]清脆的车铃声[[/dot]]。\n（1）根据拼音写汉字。\nxiàn  mù　   　\n（2）填入第⑤段括号里的句子，符合语境的一项是　   　\nA．顶着火辣辣的太阳B．冒着冷丝丝的寒风\nC．踩着金灿灿的落叶D．迎着雾蒙蒙的细雨\n（3）小说以“单车”为线索，情节生动。请在括号里填写恰当的内容。\n母亲购买旧车﹣　   　﹣　   　 ﹣父子骑车看病\n（4）第⑨段与第⑦段内容基本相同，简析作者这样写的用意。\n（5）细读第㉔段，紧扣加点之处，说说结尾的妙处。",
          "answer": "（1）本题考查音节的拼写与汉字的书写能力．解答此题关键是根据平时的积累与语境写出正确的汉字字形．这里应填的词是：羡慕．\n（2）本题考查根据语境选择句子．这是一道选择题，从四个选项内容来看，都表示了事件发生时的时间，结合前后内容来看，刘伟离家而去是在父亲砸车的第二天，全文并没有环境描写，没有交代那时的季节，但从“父亲看了看儿子，脸和胳膊都晒得黑黝黝的”，可以判断是在夏天”这句话分析，故选A合适，为下文为一情节的出现作铺垫．\n（3）本题考查情节的梳理．解答此题在整体感知文本内容的基础上，理清思路，抓住主要线索，即可概括出其他的情节．小说在写母亲买回旧车后，因为刘伟天天骑车出去混，父亲生气砸车；刘伟生气离家而去，实则搬砖挣钱买车；最后写父亲弄清了真相，高兴地与儿子一起去医院．\n（4）本题考查情节的理解与概括能力．解答此题关键要看事物出现前文章写了什么，事物出现后故事情节有了什么变化．然后根据理解，揣摩作者写作的意图，把切题的答案拟写出来．两段的内容相似却反复出现，从修辞的角度来分析，是为了强调这二人的动作，母亲“留饭”和父亲“揭开锅盖看”其实都是他们想念儿子的表现，强调他们对儿子的思念程度之深．据此整理出答案即可．\n（5）本题考查小赏析说结尾的妙处．解答此题可从结构与内容两方面分析．结加点词语来看，父亲的动作“环住”表现了他对儿子的认可；儿子“一震”表现他感受到了父爱，心里的激动；“车铃声”则起到了渲染气氛的作用．表现小说的主旨；同时在结构上，总结全文，并篇末点题．\n答案：\n（1）羡慕\n（2）A\n（3）父亲生气砸车      刘伟挣钱买车\n（4）示例：⑦⑨两段都写了母亲“留饭”和父亲“揭开锅盖看”的情节．这些重复动作蕴含着父母对儿子的牵挂，突出了对孩子的爱；也为后文父子矛盾的解决做了铺垫．\n（5）①“环住”体现了父亲对儿子的认可；②身体“一震”也是内心的震动，表明刘伟体会到了父亲的信任与关爱；③“车铃声”渲染了父子和好带来的愉悦；④结尾储蓄而巧妙地表现了主题：一个曾经叛逆的少年在父母的关爱和生活的磨炼中获得了成长．\n三、综合运用",
          "explanation": null,
