          "stem": "（二）阅读下面的诗，完成第6-7题（4分）\n卖炭翁（节选）\n白居易\n卖炭翁，伐薪烧炭南山中。\n满面尘灰烟火色，两鬓苍苍十指黑。\n卖炭得钱何所营？身上衣裳口中食。\n可怜身上衣正单，心忧炭贱愿天寒。\n6. 卖炭翁“卖炭”是为了换得                和                 。（2分）\n7. 下列对诗歌内容理解正确的一项是（     ）（2分）\nA．“伐薪烧炭”强调了卖炭翁劳动生活十分艰辛。\nB．“何所营”交代了卖炭翁穷困不堪的生活状况。\nC．“可怜”表现了作者对卖炭翁艰难处境的同情。\nD．“愿天寒”突出了卖炭翁不怕天寒地冻的精神。",
