          "stem": "（四）阅读下文，完成第11—13题（12分）\n楚人谓虎为老虫，姑苏人谓鼠为老虫。余官长洲，以事至娄东，宿邮馆①④，灭烛就寝，忽碗碟砉然②有声。余问故，阍③童答曰：“老虫”。 余楚人也，不[[dot]]胜[[/dot]]惊错，曰：“城中安得有此兽？”童曰：“非他兽，鼠也。”余曰：“鼠何[[dot]]名[[/dot]]老虫？”童谓吴俗相传尔耳。 嗟乎！鼠冒老虫之名，至使余惊错欲走，徐而思之，良④足发笑。然今天下冒虚名骇俗者不 寡矣。 ——（节选自《雪涛小说》） \n【注释】①邮馆：驿站旅馆。②砉（huā）然：象声词。③阍（hūn）：守门的人。④良：很。\n11. 解释下列加点的词。（4分）\n(1)不胜惊错                        (2)鼠何名老虫              \n12. “余惊错欲走”是因为                          。（4分）\n13. 作者通过这个故事讽刺了                             。（用自己的话回答）（4分）",
          "answer": "11. (1)能承受（能承担）(2)取名（命名）\n\n12. 方言的差异，而把老鼠当成老虎了。\n\n13. 假冒盛名吓唬世人的人。",
