          "stem": "（二）阅读下文，完成第19—23题（21分）\n爸爸教我读中国诗    程怡\n①十个月的时候，我得了一场可怕的脑膜炎，到了一岁半还不会说话，父母非常担心。一天，爸爸看报，我坐在他的膝上，指着某一个标题中的“上”字，爸爸说：“上？”我对他表示满意，赶紧从他的膝上爬下来，拽着他走到书箱前，得意洋洋地指着书箱外“函上”的“上”字，表明我认识这个字，这件事对父母而言，真是“上上大吉”！他们不再担心我有智力障碍了。之后，爸爸开始教我读诗。\n②爸爸常教我念两个人的诗：一个是杜甫，一个是陆游。\n③依稀记得，孩提时的一个夏夜，我困极了，趴在爸爸的膝上，爸爸摇着大蒲扇，[[u]]满天的星斗朦朦胧胧的[[/u]]。“僵卧孤村不自哀，尚思为国戍轮台……”突然，爸爸那江西乡音很重的诵读声使我睁开了眼睛，我不知道那奇特的吟啸中有什么，但我一下子记住了这首诗。\n④上学前我已经会背那首《示儿》：“死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。”爸爸问我懂不懂最后那句，我很得意地嚷嚷说：“那意思就是烧香磕头的时候别忘了告诉你爸爸！”当时，爸爸高兴得眼泪都流出来了。\n⑤1959年秋，我上小学。那年冬天，爸妈因故很长时间不能住在家。姐姐是长女，照顾我和弟弟。一天晚上，爸爸出乎意料地出现在我们面前，令我们欢天喜地，难以入眠。躺在床上跟爸爸念杜甫的诗：“遥怜小儿女，未解忆长安。”爸爸问我懂不懂这诗句，我说：“我懂的，不过，爸爸想念我们的时候，我们也想念爸爸的。”爸爸不再说话，只是听我继续背他教我的诗。\n⑥爸爸生命的最后几年，完全卧床不起。每当德沃夏克的大提琴协奏曲悲鸣的旋律在蕉影婆娑的窗边响起的时候，爸爸就会喃喃吟诵杜甫的诗。他告诉我，那一刻让他想起了故乡老宅，想起了祖母和母亲。\n⑦那时我已在大学教中国古代文学，我理解父亲：人生无非家国之情，杜甫、陆游，我父亲他们这一代的知识分子，对家国，都有一种深情。父亲吟诗的声音，永远留在了我心底。\n⑧很多年后，我看见报上某篇文章引了一首绝句，感觉就像遇到了一个老熟人。我没有念过那首诗，但我熟悉那种风格。回来一查，果然是陆游的诗，“征车已驾晨窗白，残烛依然伴客愁。”我当时的感受真是难以名状。[[u]]爸爸在我童年时便种在我生命里的东西，突然宣告了它的无可移易的存在！[[/u]]（有删改）\n\n19. 对第③段画线部分分析错误的一项是（    ）（3分）\nA．写出了夏天夜晚满天繁星的景色。      B．突出了我童年学诗歌的模糊记忆。\nC．表现出了夏夜我朦胧欲睡的状态。      D．引出我被父亲吟诗声唤醒的情节。\n20. 第④段爸爸高兴得流泪，其原因是                     。（3分）\n21. 文中围绕爸爸教我读中国诗，记叙了三件事，请概括。（6分）\n(1)                                  ；\n(2)上学前，爸爸教我理解《示儿》诗中的句意；\n    (3)                                  。\n22. 根据全文，概况爸爸的形象。（4分）\n(1)                                  ；(2)                                  。\n23. 谈谈你对第⑧段画线句的理解。（5分）",
          "answer": "19. B\n\n20. 还未上学的我小小年纪居然懂得了诗的意思。\n\n21. （评分：时间、行为、结果）(1)孩提时，爸爸以自己奇特的吟啸教我记住了陆游的诗；(3)上学后，爸爸教我理解杜甫诗中思念亲人的感情。\n\n22. (1)爸爸是一个有家国情怀的知识分子；(2)爸爸又是一个深爱孩子、懂得教育的慈父。\n\n23. 爸爸教我的诗永生难忘，这些诗蕴含的精神情怀（爸爸的人格魅力）影响我的一生，表达了我对爸爸的感谢与怀念。",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
