          "type": "written",
          "category": "古诗文默写",
          "stem": "(一)默写。(15分)\n1.夜来城外一尺雪,　　　　　　　　。(《卖炭翁》)\n2.　　　　　　,脉脉不得语。(《迢迢牵牛星》)\n3.　　　　　　　　　,芳草萋萋鹦鹉洲。(《黄鹤楼》)\n4.衣带渐宽终不悔,　　　　　　　　。(《蝶恋花》)\n5.山水之乐,　　　　　　　　　。(《醉翁亭记》)",
          "answer": "1. 答案　晓驾炭车辗冰辙\n\n2. 答案　盈盈一水间\n\n3. 答案　晴川历历汉阳树\n\n4. 答案　为伊消得人憔悴\n\n5. 答案　得之心而寓之酒也\n解析　1—5题均为直接型默写。易错字词有“辗”“辙”“憔悴”。\n评析　1—5题考查考生对古诗文的识记能力,注意书写要准确、清楚。",
