          "type": "written",
          "category": "阅读理解",
          "stem": "(二)阅读下面的诗句,完成第6—7题。(4分)\n　　[甲]　欲说还休,却道天凉好个秋。(《丑奴儿·书博山道中壁》)\n[乙]　会挽雕弓如满月,西北望,射天狼。(《江城子·密州出猎》)\n[丙]　会当凌绝顶,一览众山小。(《望岳》)\n6.以上三句诗均为诗词的末句,都抒写了作者心中的渴望。请分别写出渴望的内容。(2分)\n甲句:渴望能直接抒发心中的忧愁。\n乙句:　　　　　　　。　　丙句:　　　　　　　。\n7.下列对诗句理解错误的一项是(2分)(　　)\nA.三句诗都在感情高潮时结束全篇。\nB.三句诗的内容或写眼前,或写将来。\nC.三句诗传递的情感与作者的经历相关。\nD.三句诗的内容都与题目有直接关联。",
          "answer": "6. 答案　渴望建功立业　渴望登上泰山\n解析　此题要从这几句诗词的内容和位置入手,结合诗词的创作背景和主旨作答。\n\n7. 答案　D　甲句内容与题目无关。",
