          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "三、综合运用(11分)\n　　阅读下面材料,完成第23—25题。(11分)\n材料一\n一放学,宽敞的弄堂里就成了我们的乐园:男孩子们溜旱冰、踢小皮球,女孩子跳橡皮筋、造房子……那时我们玩的游戏,都是需要集体完成的,而且必有营垒相对的两方,且有输有赢,无形中让我们从小就习惯了凡事都有输赢。这局输了没关系,下局可以翻过来。最重要的是,让我们很小就培养了团队合作精神,以便争得赢局。\n(节选自程乃珊《童年的弄堂游戏》)\n材料二\n弄堂曾是上海人最常见的生活空间。弄堂游戏种类繁多,有打弹子、滚铁圈、放鹞子(风筝)、抽陀螺等。一般游戏需两人或两人以上完成。游戏“道具”大多可以自制。规则简单,易于开展。\n材料三\n本报讯　日前,上海市市西邮政公司举办了《中国主题剪影弄堂游戏》的新邮首发仪式。该套邮票以独特的剪影方式表现主题,画面生动鲜活,是了解和宣传上海本土文化的载体。\n\n　　为宣传推广“上海弄堂游戏”,班级准备设计专题板报,请你完成相关任务。\n23.板报栏目一　弄堂游戏我介绍(4分)\n弄堂游戏的特点:(1)　　　　　;(2)　　　　　;(3)规则简单,易于开展。\n弄堂游戏的益处:　。\n24.板报栏目二　赏邮看画我参与(3分)\n请选择一枚邮票,描述邮票中的画面。要求:35字左右,运用一种修辞方法。\n答:\n\n25.板报栏目三　献计献策我出力(4分)\n以下是征集到的宣传推广“上海弄堂游戏”的活动策略,不合适的两项是(　　)\nA.组织社区小伙伴进行溜旱冰比赛　　　B.开展弘扬上海乡土文化的征文活动\nC.校园网介绍“弄堂游戏”动漫作品\tD.体育课程增设“弄堂游戏”教学内容\nE.穿着印有滚铁圈图案的T恤衫\tF.在老弄堂里表演地方戏曲——沪剧\n【配图】弄堂游戏邮票（跳皮筋、斗公鸡）见本题下方。",
          "answer": "23. 答案　特点:(1)种类繁多　(2)集体完成　(3)“道具”大多可自制(写出任意两点即可)\n益处:培养团队合作精神、培养竞争意识\n解析　通读三则材料,结合题干要求提取信息,确定最终答案。如材料一中提到了溜旱冰、踢小皮球、跳橡皮筋、造房子等游戏,据此可概括为“种类繁多”;由“都是需要集体完成的”可概括为“集体完成”。\n\n24. 答案　(示例1)跳皮筋的女孩子如雏燕展翅,轻盈起跳,周围同学的脸上写满了快乐。\n(示例2)两个男孩如两头竖起犄角的小牛犊,展开角斗,旁观的同学欢呼叫好。\n解析　这是一道图文转换题。作答此题,一要审清题目要求——35字左右,运用一种修辞方法;二要结合邮票下方文字感知画面内容,重点看画面上人物的性别、数量和动作,同时要对画面加以适当的想象。\n\n25. 答案　BF　B.征文活动属于写作。F.沪剧属于地方戏曲。这两项都与“弄堂游戏”无关。",
