          "type": "written",
          "category": "作文",
          "stem": "26.题目:不止一次,我努力尝试\n要求:(1)写一篇600字左右的文章。\n(2)不得透露个人相关信息。\n(3)不得抄袭。",
          "answer": "作文没有唯一答案。原资料写作指导或评分参考：\n26.[写作指导]　这是一道全命题作文题,题目传达出三点重要信息:一是写“我”,二是“不止一次”,三是“努力尝试”。此题目适合写记叙文,记叙尝试的事件,写出“我”“不止一次”“努力尝试”的过程。尝试的事件要有价值,体现正能量。要使用多种表达方式,记叙要详略得当,抒情、议论要体现作者的感情和价值取向。要注意题目要求,写够字数,不得透露个人信息,不要抄袭。最后,书写要规范,标点要正确。",
