          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "(二)阅读下文,完成第19—23题。(20分)\n列车上\n①前两天我坐火车出差。[[u]]一路看着窗外荒凉的冬日风景,听着咣当咣当的车轮声[[/u]],实在是无聊透顶。我想找个同行的旅客,聊聊天,打发一下时间。\n②首先把目光落在了对面的小伙子身上,年龄相仿,应该有共同语言。我正在考虑用什么话来开头,只见那小伙子打开随身带的电脑包,取出笔记本,放在腿上开始上网。于是耳朵里传来了QQ的提示音,原来人家有人聊天。\n③左边是个美女,一直侧脸向窗外看着。虽说咱不贪图什么艳遇,但是如果有一位佳人旅途相伴,聊聊天,也是很不错的。我整理一下自己的衣服,清了清嗓子,用尽量绅士一些的语调说:“你好,是不是没来过这里,见你一直在欣赏外面的景色啊?”话音落下,美女却丝毫没有反应。仔细一瞧,人家秀发遮掩的耳朵里耷拉下一条黑线来,原来在静静地听音乐,把整个车厢里的人都排斥在外。\n④我灰头土脸地苦笑一下,扭头看斜对面的那个大爷。大爷穿着非常朴素,慈祥的面容,一看就是个实在人,使我想起了我的父亲。大爷似乎觉察到我的目光一直盯着他,马上把手提包抱在怀里,把头埋下去,身子向我相反的方向扭了扭。我颇为尴尬,使劲咽了口唾沫,站起身来。\n⑤我穿过车厢,走到了两节车厢的接头处,看见一个中年人在那里抽烟。我凑过去,掏出一支烟来,赔着笑说:“车厢里禁止抽烟,憋坏了,也过来抽一口。大哥,借个\n火。”中年人犹豫了一下,掏出打火机递过来。我在火车的晃荡中把烟点着,吸了一口,把打火机还给他,说:“谢谢啊,大哥这是去哪?”\n⑥中年人把还剩一大截的烟掐灭,说了声:“你接着抽,我回座位了。”\n⑦我正呆滞在那里,一个八九岁的阳光男孩出现在眼前,“叔叔,请问您,窗外那些高大笔直的树就是白杨树吗?”\n19.第①段画线部分的作用是　　　　　　　　　　　　　　　　　　。(3分)\n20.细读第②—⑥段,“我”想与人聊天却四次未能如愿,请把“我”遇挫后的“反应”填写在下列横线上。(4分)\n第一次:失望;第二次:　　　　;第三次:尴尬;第四次:　　　　。\n21.第⑥段中年人的言行传递给我们的信息是　　　　　　　　　　　　。(4分)\n22.对本文主旨概括最恰当的一项是(4分)(　　)\nA.告诫人们,身处信息化时代,不能因人机交流而忽略人际交流。\nB.警示我们,身处陌生的环境,应该注意保持适度的警觉和距离。\nC.提醒人们,在公共场合,人与人之间也要多点信任,多点交流。\nD.劝导我们,即使社会复杂,人们交流方式各异,仍需待人以礼。\n23.联系全文,简要分析小说结尾的妙处。(5分)\n答:",
          "answer": "19. 答案　渲染列车上所见所闻的单调乏味,表现“我”无聊的心境,引出下文“我”找同行者聊天的情节\n解析　这是文章开头的环境描写,作用一般有三点:一是渲染某种气氛;二是表现人物某种心情;三是为下文作铺垫。从这三个方面作答即可。\n评析　本题考查学生对环境描写的作用的分析能力,难度不大。\n\n20. 答案　苦笑　呆滞\n解析　第二次是想与美女聊天遇挫,原文中描述“我”的反应的句子“我灰头土脸地苦笑一下”,提取“苦笑”作答。第四次是想与抽烟的中年人聊天遇挫,原文中描述“我”的反应的句子“我正呆滞在那里”,提取“呆滞”作答。\n评析　本题考查学生对文章主人公情绪、情感变化的把握能力,难度不大。\n\n21. 答案　对“我”怀有戒备之心,不愿与“我”交流\n解析　从“中年人把还剩一大截的烟掐灭”和他说的“你接着抽,我回座位了”来看,显然中年人对“我”怀有戒备之心,怕“我”不是好人,不愿与“我”交流。\n评析　本题考查学生对句子言外之意的把握能力,难度适中。\n\n22. 答案　C(4分)　A(2分)　从全文来看,文中的“我”想与人聊天四次遇挫,表现的是在现实社会中,人与人之间缺乏信任,缺少交流,尤其是在公共场合。所以,选C项最恰当,可得满分4分。“告诫人们,身处信息化时代,不能因人机交流而忽略人际交流”,是对②③两段“段旨”的概括,合理但不全面,所以选A项,也可得2分。\n评析　本题考查学生对文章主旨的辨析把握能力,难度适中。\n\n23. 答案　阳光男孩的主动交流与前文其他人的表现形成反差(对比),引发我们对人际交流问题的思考。结尾戛然而止,意味深长,给人以回味和思考的空间。\n解析　把男孩的言行与前面“我”的四次经历进行对比分析,可以看出男孩的主动与前文其他人的表现形成巨大反差,从而引发我们思考。作者没有明确指出,而是把思考的余地留给读者,令人回味。\n评析　本题考查学生分析文学作品精巧结尾的能力,难度较大。",
          "explanation": null,
          "explanationNote": "已将原资料文字与标注转录，参考答案保留原资料解释；表格按行列或节点阅读，必要局部配图保留。待语文教师审核。",
