          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "三、综合运用(11分)\n阅读下面材料,完成第24—26题。(11分)\n\n爱因斯坦与上海有特殊的情缘,他曾在1922年两次到访上海。前一次他刚踏上堤岸就获悉自己得到诺贝尔物理奖的消息;后一次他在福州路工部局礼堂演讲“相对论”。这两次抵沪,他都入住在理查饭店,即今天外滩的浦江饭店。\n为了纪念这份特殊情缘,让更多市民感受这座城市的历史和文化,2008年6月,高达2.8米的爱因斯坦雕像(见右图)在上海城市雕塑中心揭幕。按原计划,这尊雕像将安放在上海的某一个地方。当时有媒体称“爱因斯坦,这个全世界最聪明的‘头脑’,从此常住上海”。谁也没有想到,6年过去了,由于种种原因,这尊雕像至今仍存放在上海城市雕塑中心。此事引发了上海市民的热议。\n24.假设可以在以下地点安放爱因斯坦雕像,你会选择哪一处?请简述理由。(4分)\nA.南京路步行街\tB.外滩街心花园\nC.东方绿舟智慧大道\tD.陆家嘴金融区\n选择:\n理由:\n25.请你为爱因斯坦雕像拟一个恰当的名字。(3分)\n答:\n\n26.如果需要在这尊雕像底座上写一段简要说明,以下不必写入的两项内容是(4分)(　　)\n　　　　　　　　　　　　　　　　　　　　　　　　\nA.雕像设计者和立像时间、单位\tB.爱因斯坦的生平事迹\nC.爱因斯坦生卒年份\tD.爱因斯坦与上海的情缘\nE.雕像四周的环境特点\tF.爱因斯坦的主要贡献\n【配图】爱因斯坦雕像见本题下方。",
          "answer": "24. 答案　示例:选B　爱因斯坦曾入住外滩浦江饭店,雕像安放在外滩街心花园,有利于市民和游客走近历史人物曾经生活过的空间,感受这座城市的历史和文化。\n解析　本题为开放性试题,选择哪个地方都可以,只要理由充分。\n\n25. 答案　最聪明的头脑(“相对论”之父)\n解析　本题为开放性试题,可以直接从材料中提取,如“最聪明的头脑”等,也可以自己结合内容拟名,如“相对论之父”等。\n\n26. 答案　B(2分)　E(2分)　因为是为了纪念那份特殊情缘才有爱因斯坦雕像的,所以只需要简单介绍生卒年份,不需要介绍生平事迹(与上海无关),更不需要写入雕像四周的环境特点。",
          "explanation": null,
