          "type": "written",
          "category": "古诗文默写",
          "stem": "(一)默写。(18分)\n1.山光悦鸟性,　　　　　。(《题破山寺后禅院》) \n2.东边日出西边雨,　　　　　　　。(《竹枝词》) \n3.　　　　　,清泉石上流。(《山居秋暝》) \n4.晨兴理荒秽,　　　　　。(《归园田居》) \n5.　　　　,亭亭净植……(《爱莲说》) \n6.虎见之,　　　　　,以为神……(《黔之驴》)",
          "answer": "1. 答案　潭影空人心\n\n2. 答案　道是无晴却有晴\n\n3. 答案　明月松间照\n\n4. 答案　带月荷锄归\n\n5. 答案　香远益清\n\n6. 答案　庞然大物也\n解析　六道小题均为一般性默写,难度不大,但应注意易错字“晴”“荷”“清”“庞”,另外注意不要漏写助词“也”字。",
          "explanation": null,
          "review": {
            "status": "pending"
          }
