          "type": "written",
          "category": "阅读与综合运用（文字）",
          "stem": "(二)阅读下文,完成第21—26题。(27分)\n和老妈过招\n①老妈89岁,正在人生的第二个童年时期,又活泼又率真。我正当中年,精力充沛。可是别以为在耄耋老人的面前你就很强大,[[u]]和老妈过招,胜算几何呢?[[/u]]\n②老妈住在我家朝阳的大南屋,家庭公共电视在她的屋里。晚上老妈总是很早吃饭,很早睡下。老妈说:“丫头啊,我睡我的,你看你的,我听不见电视的声音,一点儿也不影响我。”为着诚恳的缘故吧,老妈又说:“听话啊,我的老丫头,你看吧,愿意看到什么时候就看到什么时候。”\n③老妈真好,事儿真少,不像我有些同学或朋友的老妈,事儿多。我于是服侍老妈睡下,然后回到沙发上看电视。没看上半小时,老妈高亢的声音从我身后传来:“丫头啊,别看了,这灯光晃得我心里闹腾得不行了。”因为声音太过突然,我打个哆嗦,手中的遥控器跌落在沙发上。打完哆嗦,我赶紧关电视,关灯,关门,乖乖地退出老妈房间。\n④我另有两个房间,每间里都有电脑,坐在电脑前琢磨:老妈lì害呀,不受委屈。我心里很安慰,这个回合我输掉了,但是高兴。\n⑤老妈每天都要问我一个问题:“百合有电话吗?”百合是我女儿,在北京念大二。老妈耳朵背,我附耳回答:“有电话。”过不了多久,老妈又问:“百合有电话吗?”有时我忙着别的事情,有时心里被问得厌烦,就不到她的身边附耳回答了,[[u]]而是先在脸上堆出笑来[[/u]],口型做得大大的,表示“有”。耶!老妈居然看懂了,高高兴兴的样子。这样一天下来老妈对这个问题又问了七八遍,我就笑呵呵地回答了她七八遍。可能问到第九遍时,我趋近附耳向她质疑:“妈,您都问了我一千遍了呀。”老妈眼都不眨一下说:“哪有呢,我也就问了八百遍罢了。”\n⑥我哈哈大笑,老妈真调皮啊。这个回合我输得甘心。\n⑦一天,老妈左侧髋骨突然疼痛,自言快疼哭了。推老妈去医院拍片子,医生说骨质疏松。按照医嘱,系统补钙,喝奶,吃药,静养。为了防止出现意外骨折,我买了坐便椅,不许老妈再去卫生间。这样过了几天,老妈的腿依然疼痛难忍,面部常有痛苦不堪的表情。又过了些日子,老妈平时端坐还好,稍微运动时,表情依然痛苦,躺下歇息的时候,连毛毯都不能自己盖了。我真的很急啊,可是灵感在此刻也出现了。我躲在屋外,偷窥老妈,有巨大收获。老妈独自一人的时候,居然能够比较自如地坐到坐便椅上解决问题,也能自己很轻松地盖好又轻又暖的毛毯。做这些的时候,老妈十分平静安详。\n⑧这一次,老妈当我面微微行动时,又说疼啊疼啊,表情显得很痛苦不堪。我俯身贴耳揭她老底:“老妈,没有那么疼吧,你其实不怎么疼啊!”老妈仰脸看着我,脸上换上一种如孩童般被揭穿真相的纳罕[注]和羞赧,说:“你怎么知道的啊?”\n⑨这个回合我赢了,可是呆呆地想了想,又何必揭穿老妈呢?老妈够可怜的啦,她心里不知道有多害怕和无助呢。我把老妈搂在怀里,很是羞愧,于是这个回合我还是输掉了。\n⑩其实,我知道母女之间哪有输赢呢,或者换句话说,我输了,也就是我赢了。\n[注]　纳罕:诧异,惊奇。\n21.根据拼音写汉字。(2分)\n老妈lì　　　　害呀 \n22.第①段画线句在结构上的作用是(1)　　　　　;(2)　　　　　。(2分) \n23.联系上下文,第⑤段画线句运用的人物描写方法是　　　　描写,作用是　　　　　　　　　　　　　　　　　　　　　。(3分) \n24.根据文章内容，完成下表。（8分）\n表头：过招时“老妈”的表现｜过招后“我”的反应（外在表现、内心感受）\n第一次过招：老妈的表现（1）________；“我”外在表现：坐在电脑前琢磨；内心感受（2）________。\n第二次过招：老妈的表现：反复问同一个问题；“我”外在表现（3）________；内心感受（4）________。\n第三次过招：老妈的表现（5）________；“我”外在表现（6）________；内心感受：羞愧。\n25.对本文主旨理解最恰当的一项是(4分)(　　)\nA.抒写了人世间亲情的美好。\nB.提醒我们做人要诚实守信。\nC.启发我们要尊重和关心老人。\nD.告诉我们要理解老人的心理需求。\n26.请你根据本文内容,展开合理想象,在下面文字后续写“百合”与外婆见面时的情景。(80字左右)(8分)\n　　“百合”知道了外婆对她的思念,放假了,“百合”回家见到了外婆。\n答:",
          "answer": "21. 答案　厉\n解析　根据语境进行拼写,加强对形近字的识别。\n\n22. 答案　(1)照应标题　(2)引出下文“过招”的内容\n解析　放在篇首的语句,结构上的作用一般有以下几种:开篇点题、引起下文、设下悬念、作铺垫等。联系全文的内容可以判断出其作用。\n\n23. 答案　肖像　委婉地写出了“我”对老妈多次问话的厌烦,又体现了“我”对老妈的尊重\n解析　由“脸上堆出笑来”可以判断其为肖像描写。由上文可知,“我”虽说对老妈当时多次发问深感不满,但对自己的妈妈还是很尊重的。\n\n24. 答案　(1)前后矛盾　(2)高兴　(3)哈哈大笑　(4)甘心　(5)夸大病情　(6)搂、呆想\n解析　(1)(5)考查事件的概括。(3)(6)考查相应段落中关键词的提取,答案可以在第⑥段和第⑨段中找到。(2)(4)的答案可以在第④段和第⑥段中找到。\n评析　本题考查考生筛选和概括信息的能力,有一定难度。\n\n25. 答案　D(4分)　C(2分)　A(1分)　本文共记叙了三件事,而母亲前后矛盾、调皮、故意夸大病情只是想引起“我”的关注,作者想以此告诉我们要理解老人的心理需求。因此最合适的选项应是D。\n\n26. 答案　要点:语言　内容\n(示例)百合回家见到了外婆,马上跑到了外婆的身边,搂着她的脖子,兴奋地说:“外婆,你好吗?我可想你了,你知道吗?我在学校时做梦都梦见你了,你有没有梦见我呀?……”这小丫头从小由外婆一人带大,这不一进门就跟外婆有说不完的话,而老妈脸上的笑容是平日里我从未见过的……\n解析　本题为开放性试题,答案不唯一。根据题目的要求,需展开合理的想象,续写百合与外婆相见时的情景。可抓住百合的语言、动作、神态等进行细致的刻画。",
          "explanation": null,
