          "stem": "27.题目:今天,我想说说心里话\n要求:(1)写一篇600字左右的文章。\n(2)不得透露个人相关信息。\n(3)不得抄袭。",
          "answer": "作文没有唯一答案。原资料写作指导或评分参考：\n27.[写作指导]　这是一道全命题作文题。考生应该根据要求,认真审题。从题目中的中心词“心里话”可看出这个标题适合写成记叙类文章。从“今天”一词可以推断心里话是以前应该说、想要说,但没有机会说的,现在时机成熟了,可以说了,或者到了不得不说的时刻了。那么,你究竟有什么心里话要说呢?",
