          "originalNo": 3,
          "type": "choice",
          "category": "选择题",
          "stem": "2025年上海科技节主题曲《科创之城》，我们能分辨出不同乐器演奏同一首歌，是因为（ ）",
          "answer": "C",
          "explanation": "声音的响度与声源振动的幅度有关，振动幅度越大，响度越大，响度还与距离发声体的远近有关；而音调的高低与发声物体振动频\n率有关，物体振动越快，音调越高；音色反映了声音的品质与特色，不同发声体的材料和结构不同，发出声音的音色不同，我们能\n分辨出不同乐器演奏同一首歌，是因为声音的音色不同。\n故选：C。",
