          "stem": "物理兴趣小组同学在做凸透镜成像实验时，光屏和发光体在透镜的______(选填“同侧”或“两侧”)，它们的中心在\n______上，此凸透镜的焦距为10厘米，发光体距离凸透镜16厘米时，成______(选填“正立放大”、“正立缩小”、“倒立放\n大”或“倒立缩小”）的实像。",
          "answer": "物理兴趣小组同学在做“探究凸透镜成像实验”时，光屏和发光体在透镜的两侧，它们的中心在主光轴上，此凸透镜的焦距为10cm\n，发光体距离凸透镜16cm时，成倒立放大的实像。\n故答案为：两侧；主光轴；倒立放大。",
          "explanation": "做“探究凸透镜成像实验”时，光屏和发光体在透镜的两侧，为了使像成在光屏中央，应调节凸透镜、烛焰和光屏的高度，使它们的\n中心大致在同一高度上。根据f <u<2f，成倒立、放大的实像。",
